/**
 * Stage Render service.
 * Redraws the engineering design stage for a design from data, instead of
 * using a screenshot. The drawing uses:
 *  - the tile layout recorded when the design was run ({ A: "grass", ... }),
 *  - the design history row (rainfall, runoff, absorption, cost, pollution)
 *    for the gauges and watchers,
 *  - static assets taken from the UVA-ED-project template
 *    (public/stage-render, regenerated by scripts/extract-stage-assets.py).
 * Positions, scales and layering copy the NetsBlox stage so the result
 * matches what the student saw after the run.
 */

const BASE = `${process.env.BASE_URL || "/"}stage-render/`;
const WATCHER_COLOR = "rgb(243,118,29)";

let manifestPromise = null;
const imageCache = {};
const renderCache = new Map();

function loadManifest() {
  if (!manifestPromise) {
    manifestPromise = fetch(BASE + "manifest.json")
      .then((response) => {
        if (!response.ok) throw new Error("stage manifest not found");
        return response.json();
      })
      .catch((error) => {
        manifestPromise = null;
        throw error;
      });
  }
  return manifestPromise;
}

function loadImage(path) {
  if (!imageCache[path]) {
    imageCache[path] = new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = () => {
        delete imageCache[path];
        reject(new Error("could not load " + path));
      };
      img.src = BASE + path;
    });
  }
  return imageCache[path];
}

/** "$37,500" / "1.25" / 3 -> number (NaN when not numeric). */
function toNumber(value) {
  if (typeof value === "number") return value;
  if (value === undefined || value === null) return NaN;
  return parseFloat(String(value).replace(/[^0-9.-]/g, ""));
}

/**
 * Gauge costume, as computed by the gauge sprites' "time elapsed" script:
 * val = round(value * 2 + 0.49); 0 when val <= 0, 10 when val > 10,
 * otherwise "switch to costume (val + 1)", i.e. costume number val + 1,
 * which is the costume named val.
 */
function gaugeLevel(value) {
  const n = toNumber(value);
  if (isNaN(n)) return 0;
  const val = Math.round(n * 2 + 0.49);
  return Math.min(Math.max(val, 0), 10);
}

/** Value shown for a watcher, taken from the design history row. */
function watcherValue(variable, design) {
  const fieldByVar = {
    "total cost": "cost",
    "total pollution": "total pollution",
  };
  const raw = design[fieldByVar[variable] || variable];
  if (raw === undefined || raw === null || raw === "") return "";
  const n = toNumber(raw);
  return isNaN(n) ? String(raw) : String(n);
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

/** Approximation of a Snap variable watcher: grey box, label, orange cell. */
function drawWatcher(ctx, x, y, label, value) {
  ctx.save();
  ctx.font = "bold 10px Helvetica, Arial, sans-serif";
  ctx.textBaseline = "middle";
  const labelWidth = ctx.measureText(label).width;
  const valueWidth = Math.max(ctx.measureText(value).width, 6);
  const h = 18;
  const cellW = valueWidth + 10;
  const w = labelWidth + cellW + 16;
  roundRect(ctx, x, y, w, h, 8);
  ctx.fillStyle = "rgb(220,220,220)";
  ctx.fill();
  ctx.strokeStyle = "rgb(170,170,170)";
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.fillStyle = "rgb(60,60,60)";
  ctx.fillText(label, x + 6, y + h / 2 + 0.5);
  roundRect(ctx, x + labelWidth + 10, y + 3, cellW, h - 6, 5);
  ctx.fillStyle = WATCHER_COLOR;
  ctx.fill();
  ctx.fillStyle = "white";
  ctx.fillText(value, x + labelWidth + 15, y + h / 2 + 0.5);
  ctx.restore();
}

function drawSprite(ctx, img, manifest, x, y, scale, cx, cy) {
  const { width, height } = manifest.stage;
  ctx.drawImage(
    img,
    width / 2 + x - cx * scale,
    height / 2 - y - cy * scale,
    img.width * scale,
    img.height * scale
  );
}

export default {
  /**
   * Stable identifier of a design history row, used to link it to its
   * recorded tile layout ("<design>. <date>" is unique per run).
   */
  designKey(design) {
    return design ? String(design["design/date"] || "") : "";
  },

  /**
   * Render a design's stage.
   * @param {Object} design formatted design history row (Visualize.getObject).
   * @param {Object} materials tile layout, e.g. { A: "grass", D: "concrete" }.
   * @returns {Promise<string>} PNG data URL of the stage.
   */
  async renderDesign(design, materials) {
    const cacheKey = JSON.stringify([
      this.designKey(design),
      design.rainfall,
      design.runoff,
      design.absorption,
      design.cost,
      design["total pollution"],
      materials,
    ]);
    if (renderCache.has(cacheKey)) return renderCache.get(cacheKey);

    const manifest = await loadManifest();
    const canvas = document.createElement("canvas");
    canvas.width = manifest.stage.width;
    canvas.height = manifest.stage.height;
    const ctx = canvas.getContext("2d");
    ctx.imageSmoothingQuality = "high";
    ctx.fillStyle = "white";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(await loadImage(manifest.background), 0, 0);

    const gaugeValues = {
      rain: design.rainfall,
      runoff: design.runoff,
      absorption: design.absorption,
    };
    const tileCenter = manifest.tileCenter;

    // layers are listed back to front, as in the NetsBlox stage
    for (const layer of manifest.layers) {
      let path;
      let cx = layer.cx;
      let cy = layer.cy;
      if (layer.type === "tile") {
        const material = (materials && materials[layer.name]) || "clear";
        path =
          manifest.tileMaterials[material] || manifest.tileMaterials.clear;
        cx = tileCenter.cx;
        cy = tileCenter.cy;
      } else if (layer.type === "gauge") {
        path = layer.prefix + gaugeLevel(gaugeValues[layer.gauge]) + ".png";
      } else {
        path = layer.image;
      }
      const img = await loadImage(path);
      drawSprite(ctx, img, manifest, layer.x, layer.y, layer.scale, cx, cy);
    }

    (manifest.watchers || []).forEach((watcher) => {
      drawWatcher(
        ctx,
        watcher.x,
        watcher.y,
        watcher.var,
        watcherValue(watcher.var, design)
      );
    });

    const url = canvas.toDataURL("image/png");
    renderCache.set(cacheKey, url);
    return url;
  },
};
